      code: 'import sqlite3\nimport pandas as pd\nfrom contextlib import contextmanager\n\n@contextmanager\ndef get_db(db_path="warehouse.db"):\n    conn = sqlite3.connect(db_path)\n    conn.execute("PRAGMA journal_mode=WAL")\n    conn.execute("PRAGMA synchronous=NORMAL")\n    try:\n        yield conn\n    finally:\n        conn.close()\n\n# Create schema\nwith get_db() as conn:\n    conn.executescript("""\n        CREATE TABLE IF NOT EXISTS sales (\n            id INTEGER PRIMARY KEY,\n            date TEXT,\n            product TEXT,\n            quantity INTEGER,\n            price REAL,\n            region TEXT\n        );\n        CREATE INDEX IF NOT EXISTS idx_date ON sales(date);\n        CREATE INDEX IF NOT EXISTS idx_product ON sales(product);\n    """)\n\n# Insert data\nimport random\nwith get_db() as conn:\n    data = [(f"2024-{random.randint(1,12):02d}-{random.randint(1,28):02d}",\n             random.choice(["Widget", "Gadget", "Doohickey"]),\n             random.randint(1, 100),\n             round(random.uniform(10, 100), 2),\n             random.choice(["North", "South", "East", "West"]))\n            for _ in range(10000)]\n    conn.executemany("INSERT INTO sales (date, product, quantity, price, region) VALUES (?,?,?,?,?)", data)\n\n# Analytical queries\nwith get_db() as conn:\n    # Monthly revenue by product\n    df = pd.read_sql_query("""\n        SELECT \n            substr(date, 1, 7) as month,\n            product,\n            SUM(quantity * price) as revenue,\n            COUNT(*) as transactions,\n            AVG(quantity) as avg_qty\n        FROM sales\n        GROUP BY month, product\n        ORDER BY month, revenue DESC\n    """, conn)\n    print(df.head(10))',
