      code: 'from pymongo import MongoClient\nfrom datetime import datetime\nimport json\n\nclient = MongoClient("mongodb://localhost:27017")\ndb = client["eventstore"]\nevents = db.events\nprojections = db.projections\n\n# Append events (immutable log)\ndef append_event(aggregate_id, event_type, data):\n    events.insert_one({\n        "aggregate_id": aggregate_id,\n        "event_type": event_type,\n        "data": data,\n        "timestamp": datetime.now(),\n        "version": events.count_documents({"aggregate_id": aggregate_id}) + 1,\n    })\n\n# Build projection (read model)\ndef build_user_projection(user_id):\n    pipeline = [\n        {"$match": {"aggregate_id": user_id}},\n        {"$sort": {"version": 1}},\n        {"$group": {\n            "_id": "$aggregate_id",\n            "events": {"$push": "$$ROOT"},\n            "latest_version": {"$max": "$version"},\n        }},\n    ]\n    \n    result = list(events.aggregate(pipeline))\n    if not result:\n        return None\n    \n    state = {}\n    for event in result[0]["events"]:\n        if event["event_type"] == "user_created":\n            state = {"name": event["data"]["name"], "email": event["data"]["email"]}\n        elif event["event_type"] == "user_updated":\n            state.update(event["data"])\n        elif event["event_type"] == "user_deleted":\n            state["deleted"] = True\n    \n    state["version"] = result[0]["latest_version"]\n    return state\n\n# Usage\nappend_event("user_123", "user_created", {"name": "Alice", "email": "alice@example.com"})\nappend_event("user_123", "user_updated", {"name": "Alice Smith"})\nappend_event("user_123", "user_updated", {"email": "alice.smith@example.com"})\n\nprojection = build_user_projection("user_123")\nprint(f"User state: {projection}")',
