      code: 'import pytest\nfrom hypothesis import given, strategies as st\n\n# Function to test\ndef sort_list(items):\n    """Sort a list of integers."""\n    return sorted(items)\n\n# Property: sorted list is always ascending\n@given(st.lists(st.integers()))\ndef test_sort_is_ascending(items):\n    result = sort_list(items)\n    for i in range(len(result) - 1):\n        assert result[i] <= result[i + 1]\n\n# Property: sorted list has same length\n@given(st.lists(st.integers()))\ndef test_sort_preserves_length(items):\n    assert len(sort_list(items)) == len(items)\n\n# Property: sorted list contains same elements\n@given(st.lists(st.integers()))\ndef test_sort_preserves_elements(items):\n    assert sorted(sort_list(items)) == sorted(items)\n\n# Property: sort is idempotent\n@given(st.lists(st.integers()))\ndef test_sort_idempotent(items):\n    assert sort_list(sort_list(items)) == sort_list(items)\n\n# Parametrized tests with edge cases\n@pytest.mark.parametrize("input,expected", [\n    ([], []),\n    ([1], [1]),\n    ([3, 1, 2], [1, 2, 3]),\n    ([1, 1, 1], [1, 1, 1]),\n    ([-1, 0, -2], [-2, -1, 0]),\n])\ndef test_sort_parametrized(input, expected):\n    assert sort_list(input) == expected',
